"use client";

import { useState } from "react";
import Link from "next/link";
import Image from "next/image";
import { usePathname } from "next/navigation";

const links = [
  { href: "/",        label: "Home" },
  { href: "/service", label: "Service" },
  { href: "/gallery", label: "Gallery" },
  { href: "/contact", label: "Contact" },
];

export default function Navbar() {
  const [open, setOpen] = useState(false);
  const pathname = usePathname();

  return (
    <header className="shadow-md relative z-50">

      {/* ── Main Navbar ── */}
      <div className="flex items-center justify-between px-6 lg:px-10 py-2
        bg-[linear-gradient(90deg,rgb(109,15,172)_0%,rgba(253,29,29,1)_60%,rgba(252,176,69,1)_100%)]
        text-white">

        {/* Logo */}
        <Link href="/" className="flex items-center">
          <Image
            src="/header-logo-12.png"
            alt="Lovely Looks"
            width={640}
            height={500}
            priority
            className="h-12 lg:h-17 w-auto"
          />
        </Link>

        {/* Desktop Menu */}
        <nav className="hidden lg:flex items-center gap-6 text-base font-semibold">
          {links.map(({ href, label }) => {
            const active = pathname === href;
            return (
              <Link
                key={href}
                href={href}
                className={`relative tracking-widest transition-opacity duration-200
                  ${active ? "opacity-100" : "opacity-80 hover:opacity-100"}`}
              >
                {label.toUpperCase()}
                {active && (
                  <span className="absolute -bottom-1 left-0 w-full h-0.5 bg-white rounded-full" />
                )}
              </Link>
            );
          })}

          {/* Desktop Book Now */}
          <Link
            href="/contact"
            className="ml-2 px-5 py-2 bg-white text-purple-700 text-sm font-bold
              tracking-wider rounded-md hover:opacity-90 transition-opacity"
          >
            BOOK NOW
          </Link>
        </nav>

        {/* Hamburger */}
        <button
          onClick={() => setOpen(true)}
          className="lg:hidden text-2xl leading-none"
        >
          ☰
        </button>
      </div>

      {/* Backdrop */}
      {open && (
        <div
          className="fixed inset-0 bg-black/40 z-[99999]"
          onClick={() => setOpen(false)}
        />
      )}

      {/* Drawer panel — right side */}
      <div
        className={`fixed top-0 right-0 h-full w-2/3 max-w-[280px]
          bg-[rgb(156,8,156)] text-white shadow-2xl z-[100000]
          flex flex-col p-6
          transition-transform duration-300 ease-in-out
          ${open ? "translate-x-0" : "translate-x-full"}`}
      >
        {/* Close */}
        <button
          onClick={() => setOpen(false)}
          className="self-start mb-6 text-2xl leading-none"
        >
          ✕
        </button>

        {/* Logo */}
        <div className="mb-8">
          <Image
            src="/header-logo-12.png"
            alt="Lovely Looks Logo"
            width={120}
            height={40}
            className="h-10 w-auto object-contain"
          />
        </div>

        {/* Links */}
        <ul className="space-y-6 text-lg font-bold flex-1">
          {links.map(({ href, label }) => {
            const active = pathname === href;
            return (
              <li key={href}>
                <Link
                  href={href}
                  onClick={() => setOpen(false)}
                  className={`block transition-opacity duration-200
                    ${active ? "opacity-100 underline underline-offset-4" : "opacity-80 hover:opacity-100"}`}
                >
                  {label}
                </Link>
              </li>
            );
          })}
        </ul>

        {/* Mobile Book Now */}
        <Link
          href="/contact"
          onClick={() => setOpen(false)}
          className="mt-6 block text-center py-3 bg-white text-purple-700
            font-bold text-sm tracking-wider rounded-lg hover:opacity-90 transition-opacity"
        >
          Book an Appointment
        </Link>
      </div>

    </header>
  );
}